var CHIPS=["Wasser holen","Bewegen","Frische Luft","Augen ausruhen","Etwas essen","Nachrichten beantworten"];
var day=1;
function hm(s){var a=s.split(":");return +a[0]*60+ +a[1]}
function ttHTML(day){
  var d=DAYS[day],h="";
  d.rows.forEach(function(r,i){
    var p=r[4]==="p",dur=hm(r[1])-hm(r[0]);
    h+='<div class="row'+(p?" pause":"")+'" data-i="'+i+'"><div class="t">'+r[0]+' bis '+r[1]+'<small>'+dur+' Min</small></div><div>';
    h+='<h3>'+esc(r[2])+(r[5]?' <a class="go" href="'+r[5]+'">'+esc(r[6])+' →</a>':'')+'</h3>';
    if(r[3])h+='<p>'+esc(r[3])+'</p>';
    if(p){
      var id="pause-"+day+"-"+i;
      h+='<div class="plan"><label for="'+id+'">Das mache ich in dieser Pause</label><input type="text" id="'+id+'" data-k="'+id+'" autocomplete="off" placeholder="zum Beispiel: einmal um den Block gehen">';
      h+='<div class="chips">'+CHIPS.map(function(c){return '<button type="button" class="chip" data-for="'+id+'">'+c+'</button>'}).join("")+'</div></div>';
    }
    h+='</div></div>';
  });
  return h;
}
function renderTT(){
  $("#tt").innerHTML=ttHTML(day);
  wireTT();
}
function wireTT(){
  $$("#tt input[data-k]").forEach(function(inp){var v=sget(inp.dataset.k);if(v)inp.value=v;inp.addEventListener("input",function(){sset(inp.dataset.k,inp.value)})});
  $$("#tt .chip").forEach(function(c){c.addEventListener("click",function(){var inp=document.getElementById(c.dataset.for);inp.value=inp.value?inp.value+", "+c.textContent.toLowerCase():c.textContent;sset(inp.dataset.k,inp.value);inp.focus()})});
  tick();
}
function setDay(n){day=n;$("#tab1").setAttribute("aria-selected",n===1);$("#tab2").setAttribute("aria-selected",n===2);renderTT()}
$("#tab1").addEventListener("click",function(){setDay(1)});$("#tab2").addEventListener("click",function(){setDay(2)});

/* Live-Leiste */
function berlin(){
  var f=new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Berlin",year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit",hourCycle:"h23"});
  var o={};f.formatToParts(new Date()).forEach(function(p){o[p.type]=p.value});
  return {date:o.year+"-"+o.month+"-"+o.day,min:(+o.hour)*60+(+o.minute)};
}
function tick(){
  var n=berlin(),dk=n.date===DAYS[1].date?1:n.date===DAYS[2].date?2:0;
  var rows=$$("#tt .row");rows.forEach(function(r){r.classList.remove("now")});
  var live=$("#live"),T=$("#liveT"),S=$("#liveS");
  if(!dk){live.classList.remove("on");return}
  var d=DAYS[dk];live.classList.add("on");
  if(n.min<hm("08:30")){T.textContent="Der Tag beginnt um 08:30.";S.textContent="Zeit, in Ruhe anzukommen.";return}
  if(n.min>=hm("16:30")){T.textContent="Der Kurstag ist zu Ende.";S.textContent="Prüfe deinen Sicherungs-Check.";return}
  var cur=-1;d.rows.forEach(function(r,i){if(n.min>=hm(r[0])&&n.min<hm(r[1]))cur=i});
  if(cur<0)return;
  var r=d.rows[cur],left=hm(r[1])-n.min,msg="";
  if(r[4]==="p"){msg="Pause, noch "+left+" Min. Weiter geht es um "+r[1]+"."}
  else{var np=-1;for(var j=cur+1;j<d.rows.length;j++){if(d.rows[j][4]==="p"){np=j;break}}
    msg="Noch "+left+" Min in diesem Block."+(np>=0?" Nächste Pause um "+d.rows[np][0]+", in "+(hm(d.rows[np][0])-n.min)+" Min.":"")}
  T.textContent="Jetzt: "+r[2]+" ("+r[0]+" bis "+r[1]+")";S.textContent=msg;
  if(dk===day&&rows[cur])rows[cur].classList.add("now");
}
setInterval(tick,30000);

