function snipHTML(s,idx){
  var os=s[1]?' data-os="'+s[1]+'"':"";
  return '<div class="snip'+(s[2]==="p"?" prompt":"")+'"'+os+'><header><span>'+esc(s[0])+(s[1]?(s[1]==="win"?" · Windows":" · macOS"):"")+'</span><button type="button" class="cp" data-s="'+idx+'">Kopieren</button></header><pre></pre></div>';
}
var ALLS=[];
function build(){
  var h="";
  G.forEach(function(g){
    h+='<div class="grp" id="'+g.id+'"><h3>'+esc(g.t)+'</h3><p>'+esc(g.p)+'</p>';
    if(g.steps)h+='<ol class="steps">'+g.steps.map(function(x){return "<li><span>"+x+"</span></li>"}).join("")+'</ol>';
    h+='<div class="gridsn">';
    g.s.forEach(function(s){ALLS.push(s);h+=snipHTML(s,ALLS.length-1)});
    h+='</div>';
    if(g.n)h+='<div class="note warn" style="margin-top:0"><b>Gut zu wissen</b><p>'+esc(g.n)+'</p></div>';
    h+='</div>';
  });
  $("#groups").innerHTML=h;
  var a="";ALT.forEach(function(s){ALLS.push(s);a+=snipHTML(s,ALLS.length-1)});
  $("#alt-code").innerHTML=a;
  var L="",cur="";
  LINKS.forEach(function(l){
    if(l[0]!==cur){if(cur)L+='</div>';cur=l[0];L+='<div class="lg">'+(cur==="Danach"?"Nach dem 9. November":cur)+'</div><div class="links">'}
    L+='<a class="link" href="'+l[3]+'" target="_blank" rel="noopener"><small>'+l[0]+'</small><b>'+esc(l[1])+'</b><span>'+esc(l[4])+' · '+esc(l[2])+'</span></a>';
  });
  $("#links").innerHTML=L+'</div>';
  fill();
}
function fill(){$$(".snip").forEach(function(el){var b=el.querySelector(".cp");var s=ALLS[+b.dataset.s];el.querySelector("pre").textContent=sub(s[3])})}
document.addEventListener("click",function(e){
  var b=e.target.closest&&e.target.closest(".cp");if(!b)return;
  var txt=sub(ALLS[+b.dataset.s][3]);
  function ok(){b.textContent="Kopiert";b.classList.add("done");setTimeout(function(){b.textContent="Kopieren";b.classList.remove("done")},1600)}
  function fallback(){var pre=b.closest(".snip").querySelector("pre");var r=document.createRange();r.selectNodeContents(pre);var s=window.getSelection();s.removeAllRanges();s.addRange(r);b.textContent="Markiert, Strg+C";setTimeout(function(){b.textContent="Kopieren"},2400)}
  if(navigator.clipboard&&navigator.clipboard.writeText){navigator.clipboard.writeText(txt).then(ok,fallback)}else fallback();
});

